WITH input AS (SELECT jsonb_array_elements('[{"slug":"child-mortality","old":"احتمال الوفاة قبل الخامسة؛ قد تتضمن البيانات تقديرات نمذجة.","description":"يوضح احتمال وفاة مولود حي قبل إتمام الخامسة من عمره لكل ألف ولادة حية، بحسب تقديرات المصدر الدولي المعتمد.\n\nلماذا تهم المقارنة؟\nيكشف جانباً أساسياً من صحة الطفولة ويرتبط تفسيره بوصول الأسر إلى الرعاية والتطعيم والتغذية والمياه والصرف الصحي على المدى الطويل.\n\nكيف تقرأ الترتيب؟\nعند المقارنة تكون القيمة الأقل عادة الاتجاه المرغوب، لكن يجب النظر إلى سنة القياس ومصدر التقدير وإلى حجم الفرق الفعلي في الوفيات لكل ألف ولادة، لا المرتبة المجردة.\n\nحدود القراءة:\nلا يحدد نسبة الأطفال الذين يفتقرون إلى الغذاء أو الأمراض المسببة للوفاة، ولا يمثل عدد الضحايا الفعليين في الحرب. قد تتغير السلسلة عند مراجعة تقديرات الوفيات."},{"slug":"dependency","old":"السكان دون 15 وفوق 64 عاماً نسبةً إلى السكان بين 15 و64 عاماً.","description":"نسبة الإعالة العمرية تقارن عدد السكان دون 15 عاماً ومن بلغوا 65 عاماً فأكثر بعدد السكان من 15 إلى 64 عاماً، وتُعرض كنسبة إلى هذه الفئة العمرية.\n\nلماذا تهم المقارنة؟\nتُظهر مدى الثقل النسبي للفئات العمرية الأصغر والأكبر مقارنة بالسكان في سن العمل الاصطلاحي، ما يفيد في التخطيط للتعليم والرعاية والادخار والحماية الاجتماعية.\n\nكيف تقرأ الترتيب؟\nعند مقارنة اليمن بالدول الأخرى انتبه إلى أن انخفاض النسبة قد ينتج عن زيادة نسبة سكان سن العمل وليس تحسن الأجور. افحص التركيب العمري ومشاركة الناس فعلياً في سوق العمل قبل استنتاج العبء الاقتصادي.\n\nحدود القراءة:\nالمؤشر ديموغرافي لا يحصي المعالين مالياً بالفعل، فبعض من هم بين 15 و64 عاماً لا يعملون وبعض من خارجها يعملون. لا يقيس دخل الأسرة أو عدد أفرادها المحتاجين للدعم."},{"slug":"exports","old":"صادرات السلع والخدمات كنسبة من الناتج؛ النسبة الأكبر ليست حكماً على جودة الاقتصاد.","description":"يمثل المعيار قيمة صادرات السلع والخدمات مقارنة بالناتج المحلي الإجمالي كنسبة مئوية. يوضح وزن المبيعات الخارجية بالنسبة إلى النشاط الاقتصادي الوطني.\n\nلماذا تهم المقارنة؟\nتساعد المقارنة على معرفة درجة ارتباط إنتاج الدولة بالأسواق الخارجية وحجم أثر الطلب الدولي فيها. لكنها لا تكشف وحدها ما إذا كانت الصادرات متنوعة أو مصنّعة محلياً أو مقتصرة على سلع قليلة.\n\nكيف تقرأ الترتيب؟\nقارن نسبة اليمن بالدول الأخرى في السنة ذاتها، ثم راقب الواردات والتجارة الإجمالية لمعرفة الصورة الكاملة. ارتفاع نسبة الصادرات قد يعكس صناعة قوية أو اقتصاداً صغير المقام أو اعتماداً على سلعة رئيسية.\n\nحدود القراءة:\nالنسبة المرتفعة ليست حكماً تلقائياً على جودة الاقتصاد أو تحقيق فائض تجاري، ولا تعني أن قيمة الصادرات بالدولار هي الأعلى. تتأثر أيضاً بتغير الناتج وسعر السلع العالمية."},{"slug":"gdp","old":"قيمة الإنتاج المحلي بالأسعار الجارية بالدولار؛ حجم الاقتصاد لا يقيس رفاه الفرد.","description":"يمثل الناتج المحلي الإجمالي القيمة النقدية للسلع والخدمات النهائية المنتَجة داخل حدود الاقتصاد خلال السنة، وفق الأسعار الجارية بالدولار. يقارن هذا المعيار الحجم الاسمي للاقتصادات ولا يقيس توزيع الدخل.\n\nلماذا تهم المقارنة؟\nتُظهر مقارنة حجم الاقتصاد قدرة النشاط الإنتاجي المسجل على توليد قيمة مضافة، لكنها تحتاج إلى قراءتها بجانب نصيب الفرد والنمو الحقيقي. قد يكون اقتصاد دولة أكبر فقط لأن عدد سكانها أكبر، وليس لأن مستوى المعيشة فيها أعلى.\n\nكيف تقرأ الترتيب؟\nاقرأ قيمة اليمن والدول الأخرى لسنة واحدة بالعملة والوحدة نفسيهما، ثم قارن الاتجاه عبر السنوات وفق البيانات المتاحة. في هذا المعيار تعني المرتبة الأعلى قيمة إنتاج اسمي أكبر فقط، ولا تعني الأداء الأفضل لجميع السكان.\n\nحدود القراءة:\nالأرقام بالدولار الجاري تتأثر بالأسعار وأسعار الصرف وتقديرات الناتج؛ لا تُستخدم منفردة لقياس النمو الحقيقي أو رفاه الأسر. لا تُقارن مرتبة سنة بمرتبة أخرى دون ملاحظة الدول التي توافرت بياناتها."},{"slug":"gdp-growth","old":"التغير السنوي في الناتج الحقيقي؛ قد تكون القيمة سالبة.","description":"معدل النمو السنوي للناتج المحلي الحقيقي يقيس تغير حجم الإنتاج مقارنة بالسنة السابقة بعد استبعاد أثر تغير الأسعار وفق منهجية الحسابات القومية. قد تكون النسبة موجبة أو سالبة.\n\nلماذا تهم المقارنة؟\nيساعد على التمييز بين توسع النشاط الإنتاجي وانكماشه، خصوصاً عند تفسير سلسلة سنوات من الصدمات والتعافي الجزئي. مقارنة اليمن بدول أخرى في السنة نفسها توضّح الاختلاف في سرعة التغير، لا في الحجم الاقتصادي.\n\nكيف تقرأ الترتيب؟\nالمرتبة تُحسب من معدل النمو في السنة المختارة، لذلك قد تحتل دولة ذات اقتصاد صغير مرتبة متقدمة إذا نما إنتاجها بسرعة. يجب النظر إلى عدة سنوات متتالية وإلى المستوى الذي يبدأ منه الاقتصاد، لا سنة واحدة.\n\nحدود القراءة:\nالنمو الموجب بعد انكماش حاد لا يعني استعادة كل الإنتاج المفقود أو تحسن دخل كل أسرة. وأرقام السنوات التي يصعب فيها جمع البيانات قد تخضع لتقديرات ومراجعات لاحقة."},{"slug":"gdp-per-capita","old":"الناتج المحلي مقسوماً على السكان، بالأسعار الجارية؛ لا يوضح توزيع الدخل.","description":"نصيب الفرد من الناتج المحلي يساوي الناتج المحلي الإجمالي بالأسعار الجارية مقسوماً على تقدير السكان. إنه متوسط إنتاج اسمي محسوب بالدولار لكل فرد، لا مبلغاً يتقاضاه كل مواطن.\n\nلماذا تهم المقارنة؟\nيجعل المعيار مقارنة اقتصادات كبيرة وصغيرة السكان أكثر فائدة من الاعتماد على حجم الناتج وحده. يساعد على طرح أسئلة عن متوسط الموارد المنتجة، ويُقرأ بجانب القوة الشرائية والفقر والبطالة وتوزيع الدخول.\n\nكيف تقرأ الترتيب؟\nيمكن مقارنة قيم اليمن ودولة أخرى في السنة نفسها بعد التحقق من تغطية البيانات. الفجوة بالدولار الاسمي ليست بالضرورة فجوة مساوية في كلفة المعيشة؛ وعند تحليل التغير التاريخي يلزم الانتباه إلى نمو السكان وتغير الأسعار.\n\nحدود القراءة:\nلا يمثل متوسط الأجور أو الدخل الفعلي للأسر ولا يوضح التفاوت بين الأفراد. كما أن قياسه بالأسعار الجارية لا يصحح اختلاف مستويات الأسعار بين الدول أو آثار تغير سعر الصرف."},{"slug":"gni-per-capita","old":"الدخل القومي للفرد بطريقة أطلس للبنك الدولي.","description":"نصيب الفرد من الدخل القومي الإجمالي يُحسب من الدخل القومي مقسوماً على السكان وفق طريقة أطلس للبنك الدولي، وهو مقياس بالدولار يستخدم تحويلات مخففة لبعض تقلبات أسعار الصرف.\n\nلماذا تهم المقارنة؟\nيفيد في مقارنة متوسط الموارد المرتبطة بالمقيمين والدخول المتدفقة عبر الحدود، وليس فقط ما أُنتج داخل البلد. يساعد على فهم سبب اختلاف الدخل القومي للفرد عن الناتج المحلي للفرد عند وجود دخل أولي من الخارج وإليه.\n\nكيف تقرأ الترتيب؟\nقارن قيمة اليمن مع الدول الأخرى في سنة قياس واحدة وراعِ أن طريقة أطلس ليست تحويلة بسعر السوق في يوم معين. يفضّل مقارنته بنصيب الفرد من الناتج ومؤشرات الفقر والقوة الشرائية للحصول على صورة أوسع.\n\nحدود القراءة:\nهذا متوسط حسابي لا دخل فعلي لكل شخص، ولا يظهر توزيع الثروة أو اختلاف تكاليف المعيشة. لا يجوز اعتباره أجراً شهرياً أو مؤشراً شاملاً لجودة الخدمات."},{"slug":"health-spending","old":"نسبة الإنفاق الصحي لا تقيس وحدها جودة الرعاية أو كفاءتها.","description":"حصة الإنفاق الصحي الجاري من الناتج المحلي تمثل ما ينفق على الخدمات الصحية الجارية كنسبة إلى حجم الاقتصاد في سنة القياس، وفق حسابات الصحة الوطنية.\n\nلماذا تهم المقارنة؟\nتوضح وزن الإنفاق الصحي بالنسبة إلى الموارد الاقتصادية، ويمكن أن تساعد في طرح أسئلة حول تمويل المؤسسات والأعباء المباشرة على الأسر ودور المساعدات.\n\nكيف تقرأ الترتيب؟\nعند مقارنة اليمن بدولة أخرى، اقرأ النسبة مع قيمة الإنفاق للفرد وكفاءة الخدمة. يمكن أن ترتفع الحصة عندما يتراجع الناتج دون زيادة الإنفاق الفعلي، لذلك لا تُعد المرتبة مقياساً مباشراً لجودة الرعاية.\n\nحدود القراءة:\nلا تعني زيادة النسبة توافر الخدمات أو الأدوية أو عدالة التغطية، ولا تصف بدقة مساهمة كل جهة تمويل منفصلة. النسبة لا تقيس حجم الإنفاق الرأسمالي بالضرورة."},{"slug":"imports","old":"واردات السلع والخدمات كنسبة من الناتج المحلي.","description":"تعبّر الواردات من الناتج المحلي عن قيمة السلع والخدمات المشتراة من الخارج كنسبة إلى الإنتاج الاقتصادي المحلي خلال سنة القياس.\n\nلماذا تهم المقارنة؟\nيساعد المؤشر في قراءة اعتماد الأسواق المحلية على السلع والخدمات الخارجية، ودور الاستيراد في توفير الغذاء والدواء والآلات ومدخلات الإنتاج. ولا ينبغي وصف الاستيراد كله بوصفه ظاهرة سلبية.\n\nكيف تقرأ الترتيب؟\nقارن اليمن والدول الأخرى بناء على السنة نفسها، ثم افحص الصادرات والإنتاج المحلي لتفسير اختلاف النسب. قد ترتفع النسبة عندما يزيد الاستيراد أو عندما ينكمش الناتج المحلي، وهما أمران مختلفان.\n\nحدود القراءة:\nلا تشير النسبة إلى عجز ميزان المدفوعات أو قيمة الواردات المطلقة وحدها، ولا تكشف نوعية السلع المستوردة. انخفاضها قد يعكس اكتفاءً نسبياً أو صعوبة الحصول على الواردات."},{"slug":"infant-mortality","old":"احتمال الوفاة قبل إتمام العام الأول؛ الأقل أفضل في هذا المؤشر.","description":"معدل وفيات الرضع يعبر عن احتمال وفاة مولود حي قبل بلوغه عاماً واحداً، مقدراً لكل ألف ولادة حية وفق تعريف الرصد المستخدم.\n\nلماذا تهم المقارنة؟\nيساعد على فهم مخاطر الصحة المبكرة للأطفال وأهمية الرعاية أثناء الحمل والولادة والتطعيم والتغذية والمياه. المقارنة توضح الفروق في أحد أبعاد صحة الرضع.\n\nكيف تقرأ الترتيب؟\nفي هذا المعيار يُرتب الأقل أولاً وفق اتجاه الترتيب المعلن؛ قارِن اليمن بالدول الأخرى في سنة موحدة، ثم انظر إلى تحسن المستوى عبر الزمن لا تغير المرتبة وحده.\n\nحدود القراءة:\nليس عدداً مطلقاً للرضع المتوفين، ولا يحدد الأسباب الطبية أو يصف محافظة معينة. وقد تعتمد التقديرات على نماذج ومصادر تسجيل غير مكتملة."},{"slug":"life-expectancy","old":"متوسط سنوات الحياة المتوقعة عند الولادة وفق معدلات الوفاة الحالية.","description":"العمر المتوقع عند الولادة هو متوسط السنوات التي يمكن أن يعيشها مولود افتراضي إذا انطبقت عليه معدلات الوفيات حسب الأعمار في سنة القياس طوال حياته.\n\nلماذا تهم المقارنة؟\nيوفر مؤشراً مركباً لمستوى البقاء والصحة العامة عبر المراحل العمرية، ويفيد في مقارنة التحديات الصحية بين اليمن والدول الأخرى على المدى الطويل.\n\nكيف تقرأ الترتيب؟\nاقرأ سنوات اليمن في سياق بيانات الوفيات والرعاية والتغذية، وقارنها بسنة واحدة متوافقة مع بقية البلدان. تغيير العمر المتوقع لا يشير وحده إلى أي مرض أو خدمة صحية بعينها.\n\nحدود القراءة:\nليس متوسط أعمار من توفوا خلال تلك السنة، ولا وعداً بمقدار ما سيعيشه المولود فعلياً. يمكن أن تتأثر القيم بنماذج الوفيات ونقص تسجيل الحالات أو مراجعات المصدر."},{"slug":"maternal-mortality","old":"تقدير نسبة وفيات الأمهات المرتبطة بالحمل والولادة.","description":"وفيات الأمهات هنا نسبة تقديرية لعدد الوفيات المرتبطة بالحمل والولادة أو مضاعفاتهما لكل مئة ألف ولادة حية حسب تعريف المصدر.\n\nلماذا تهم المقارنة؟\nيساعد على وصف مخاطر الحمل والولادة وتحديات الوصول إلى الكوادر والتجهيزات الطارئة والاحالة الطبية، مع مراعاة الظروف الصحية المختلفة في البلدان.\n\nكيف تقرأ الترتيب؟\nيُحسب ترتيب اليمن من أقل نسبة إلى أعلى نسبة للعام نفسه، ويُفضّل تقييم حجم الفجوة مع الدول المقارنة ومراجعة فترات عدم اليقين في التقديرات قبل إطلاق استنتاجات قوية.\n\nحدود القراءة:\nليست نسبة من جميع النساء أو احتمال وفاة الأم خلال حياتها، ولا يمكن تفسير اختلافها بمستشفى أو سبب واحد. في البلدان محدودة التسجيل قد يكون هامش عدم اليقين واسعاً."},{"slug":"population","old":"إجمالي السكان وفق تقديرات المصدر.","description":"يقيس عدد السكان الإجمالي المقيمين بحسب تقديرات المصدر في السنة المختارة. هذا الحجم السكاني الوطني لا يساوي عدد المواطنين الموجودين داخل البلاد في لحظة بعينها.\n\nلماذا تهم المقارنة؟\nيساعد على وضع تحديات التعليم والصحة والمياه والبنية الأساسية في سياق عدد المستفيدين المحتملين، ويفسر لماذا قد تختلف حجوم اقتصادات الدول أو أعداد الطلاب والمرضى.\n\nكيف تقرأ الترتيب؟\nفي الترتيب العالمي تعني القيمة الأعلى سكاناً أكثر، لا وضعاً أفضل. عند مقارنة اليمن بدولة أخرى من المفيد الانتقال أيضاً إلى مؤشرات نصيب الفرد ومعدلات الخدمات، وعدم الاكتفاء بالأعداد المطلقة.\n\nحدود القراءة:\nالرقم تقديري ولا يقدم توزيع السكان بين المحافظات أو أعداد النازحين أو المغتربين بصورة مستقلة. تختلف المراجعات السكانية والسنوات المرجعية بين المصادر."},{"slug":"population-growth","old":"معدل النمو السنوي للسكان.","description":"معدل نمو السكان السنوي يصف التغير النسبي في إجمالي السكان بين فترتين، ويتأثر بالمواليد والوفيات وصافي الهجرة وتعديل التقديرات السكانية.\n\nلماذا تهم المقارنة؟\nيفيد في التخطيط للطلب المستقبلي على المدارس والوظائف والإسكان والمياه، ويساعد على فهم تغير الاحتياجات حتى عندما لا تتغير الموارد بالنسبة نفسها.\n\nكيف تقرأ الترتيب؟\nقارن معدل اليمن بالدول الأخرى في السنة نفسها، وراقب عدة سنوات لمعرفة استمرارية الاتجاه. النسبة العالية لا تعني بالضرورة زيادة الخصوبة وحدها، لأن الهجرة والتغيرات الإحصائية قد تساهم أيضاً.\n\nحدود القراءة:\nهو معدل نمو للسكان لا عدد المواليد أو حجم الأسرة، ولا يحدد وحده إن كان النمو مفيداً أو ضاراً. كما لا يعبّر عن توزيع الزيادة بين المناطق أو الفئات العمرية."},{"slug":"primary-enrolment","old":"يشمل المسجلين خارج العمر الرسمي؛ يمكن أن تتجاوز النسبة 100% ولا تمثل نسبة الأطفال الملتحقين.","description":"الالتحاق الإجمالي بالابتدائي يقارن جميع المسجلين في المرحلة الابتدائية، بغض النظر عن أعمارهم، بعدد الأطفال في العمر الرسمي لهذه المرحلة.\n\nلماذا تهم المقارنة؟\nيساعد على تقدير اتساع التسجيل في التعليم الأساسي والطلب على المدارس والمعلمين، لكن يجب إكماله ببيانات الحضور والإكمال وجودة التعليم.\n\nكيف تقرأ الترتيب؟\nقد تتجاوز النسبة 100% لأن المسجلين من أعمار أكبر أو أصغر يدخلون في البسط. قارن اليمن والدول الأخرى باحترام اختلاف الأنظمة الدراسية والمنهج الإحصائي ولا تعتبر النسبة العليا دائماً تحصيلاً أفضل.\n\nحدود القراءة:\nلا تعكس النسبة معدل حضور الطفل أو عدد من أكملوا المرحلة أو مستوى القراءة والرياضيات، وقد تتأثر بالإعادة والتسجيل المتأخر وعدم انتظام بيانات المدارس."},{"slug":"remittances","old":"التحويلات الشخصية الواردة كنسبة من الناتج؛ ليست مقياساً مستقلاً للرخاء.","description":"المعيار يقيس التحويلات الشخصية الواردة من الخارج إلى الاقتصاد كنسبة من الناتج المحلي خلال السنة، وفق سجلات وتقديرات ميزان المدفوعات.\n\nلماذا تهم المقارنة؟\nيمكن أن تساهم التحويلات في دعم إنفاق الأسر وتمويل احتياجاتها عند محدودية فرص العمل المحلية. والمقارنة توضح وزن هذه التدفقات بالنسبة لحجم اقتصاد اليمن واقتصادات أخرى.\n\nكيف تقرأ الترتيب؟\nاقرأ النسبة بجانب حجم الناتج الاقتصادي وتطور التحويلات بالدولار؛ فارتفاع نسبة التحويلات قد ينشأ من زيادة التدفقات أو تقلص الناتج. قارن السنة ونطاق التغطية قبل استنتاج اتجاه الاعتماد على المغتربين.\n\nحدود القراءة:\nلا يعني المؤشر أن كل أسرة تتلقى تحويلات أو أن كل الأموال الخارجية مرصودة في القنوات الرسمية. ارتفاع النسبة لا يثبت الرفاه ولا يقيس القوة الشرائية لما يصل إلى المستفيدين."},{"slug":"secondary-enrolment","old":"إجمالي المسجلين نسبةً إلى سكان العمر الرسمي؛ قد يتجاوز 100%.","description":"الالتحاق الإجمالي بالثانوي هو عدد المسجلين في هذه المرحلة من جميع الأعمار مقسوماً على عدد السكان في العمر الرسمي للتعليم الثانوي.\n\nلماذا تهم المقارنة؟\nتتيح المقارنة طرح أسئلة حول الاستمرار بعد التعليم الأساسي والقدرة الاستيعابية للمدارس، وتستكمل بمؤشرات الإكمال والتسرب والتدريب المهني.\n\nكيف تقرأ الترتيب؟\nراقب ما إذا كانت نسبة اليمن تتغير بين السنوات المتاحة، وقارنها ببلدان ذات نظم تعليم مختلفة بحذر. تجاوز 100% ممكن، لأن التعريف إجمالي لا صافٍ.\n\nحدود القراءة:\nلا يقيس مباشرة نسبة المراهقين الملتحقين من فئتهم العمرية ولا جودة التدريس أو توافر المعلمين، ولا يكشف الفوارق بين المحافظات أو الجنسين."},{"slug":"tertiary-enrolment","old":"معدل إجمالي للالتحاق بالتعليم العالي وفق تعريف المصدر.","description":"معدل الالتحاق الإجمالي بالتعليم العالي يقارن جميع الملتحقين بمؤسسات التعليم العالي مع سكان الفئة العمرية المرجعية للمرحلة، بغض النظر عن أعمار الطلاب.\n\nلماذا تهم المقارنة؟\nيساعد في تقييم حجم الوصول إلى التعليم ما بعد الثانوي مقارنة بحجم الفئة العمرية، ويثير أسئلة عن المقاعد والتخصصات والانتقال إلى سوق العمل.\n\nكيف تقرأ الترتيب؟\nقارن أحدث سنة متاحة لليمن ببيانات الدول الأخرى في السنة ذاتها، ولا تستخدم مراتب من سنوات مختلفة كأنها مقارنة مباشرة. يجب النظر أيضاً إلى أعداد الخريجين وتخصصاتهم وسوق الوظائف.\n\nحدود القراءة:\nلا يقيس الاعتماد الأكاديمي أو جودة التعليم أو معدلات التخرج والتوظيف، وقد تتأثر النسبة بمدى شمول المؤسسات العامة والخاصة وتغطية البيانات."},{"slug":"trade","old":"مجموع الصادرات والواردات؛ قد تتجاوز النسبة 100%.","description":"التجارة من الناتج المحلي هي مجموع الصادرات والواردات من السلع والخدمات مقسوماً على الناتج المحلي الإجمالي. قد يتجاوز الناتج 100% لأن التجارة الإجمالية ليست جزءاً واحداً من الناتج.\n\nلماذا تهم المقارنة؟\nيوضح المعيار درجة انفتاح النشاط الاقتصادي على المبادلات الدولية وفق مقياس نسبي. يفيد في مقارنة ارتباط اليمن بالأسواق الخارجية مقارنة باقتصادات تتفاوت في الحجم والموارد.\n\nكيف تقرأ الترتيب؟\nراقب السنة المختارة وقيمة الناتج المحلي معاً. النسبة الأعلى تعني حجماً أكبر للتبادل مقارنة بالناتج، لكنها لا تحدد ما إذا كان البلد يصدر أكثر مما يستورد أو يعتمد على سلع استراتيجية.\n\nحدود القراءة:\nليست النسبة مقياساً مباشراً للكفاءة الاقتصادية أو الرفاه أو الفائض التجاري؛ فقد ترتفع بسبب انخفاض الناتج. ولتقييم تنوع التجارة يجب الرجوع إلى تركيبة السلع والشركاء التجاريين."},{"slug":"urban-population","old":"تعريف المناطق الحضرية يختلف بين البلدان.","description":"يعرض المعيار حصة السكان المصنفين حضريين من إجمالي السكان وفق التعاريف الوطنية المستخدمة في تجميع البيانات الدولية، والتي قد تختلف بين البلدان.\n\nلماذا تهم المقارنة؟\nيساعد على دراسة اتجاه الاستقرار في المدن والطلب على النقل والإسكان والمياه والخدمات الحضرية، ومقارنته بطبيعة الريف والاقتصاد.\n\nكيف تقرأ الترتيب؟\nتُقرأ نسبة اليمن مع الانتباه إلى تعريف الحضر المستخدم، ثم إلى حجم السكان المطلق وكثافة المدن. إذا اختلفت قوانين أو معايير تصنيف المناطق، فقد لا تكون النسب متطابقة في المعنى بين البلدان.\n\nحدود القراءة:\nلا تساوي نسبة المساكن الجيدة أو فرص العمل الحضرية، ولا تعني أن بقية السكان يعملون بالزراعة. كما لا توضح أحياء بعينها أو جودة الخدمات أو أثر النزوح على المدن."}]'::jsonb) AS item),
updated AS (
 UPDATE public.ranking_indicators i SET description=input.item->>'description',updated_at=now()
 FROM input WHERE i.slug=input.item->>'slug' AND i.is_published AND i.description=input.item->>'old'
 RETURNING i.slug
) SELECT (SELECT count(*) FROM input) AS planned,(SELECT count(*) FROM updated) AS updated;
